def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def checked(path,record):
    path=Path(path)
    if path.stat().st_size>=100000:
        raise ValueError('Complete source exceeded the declared per-file review limit')
    raw=path.read_bytes()
    if len(raw)!=record['bytes'] or digest(raw)!=record['sha256']:
        raise ValueError('Changed complete source: '+str(path))
    return raw

def run(repo,outdir,*,verify_existing=False):
    repo=Path(repo).resolve();outdir=Path(outdir).resolve()
    if outdir==repo or repo in outdir.parents:
        raise ValueError('Use separate scratch for source reproduction')
    outputs={}
    for i,record in enumerate(PARTS):
        path=repo/record['path'];checked(path,record)
        name='_run10_N4096_complete_source_part_'+str(i)
        spec=importlib.util.spec_from_file_location(name,path)
        module=importlib.util.module_from_spec(spec);sys.modules[name]=module
        spec.loader.exec_module(module)
        outputs.update(module.reproduce(repo,outdir,verify_existing=verify_existing))
        checked(path,record)
    for record in SHARED:
        raw=checked(repo/record['path'],record);target=outdir/record['name']
        if verify_existing:checked(target,record)
        else:
            if target.exists() and target.read_bytes()!=raw:
                raise ValueError('Do not replace a different shared source')
            target.write_bytes(raw)
        outputs[record['name']]=dict(bytes=len(raw),sha256=digest(raw))
    by_name={record['name']:record for record in RUNTIME}
    checked_roles={}
    for role,(relative,expected) in ROLES.items():
        name=Path(relative).name
        generated=by_name.get(name)
        path=(outdir/name if generated is not None and generated['sha256']==expected
              else repo/'topics/visible-flex-larger-amplitude'/relative)
        if path.stat().st_size>=100000:
            raise ValueError('Role is not an entire reviewable source: '+role)
        raw=path.read_bytes()
        if digest(raw)!=expected:
            raise ValueError('Changed complete actual source role: '+role)
        checked_roles[role]=dict(path=str(path),bytes=len(raw),sha256=digest(raw))
    if len(outputs)!=19 or len(checked_roles)!=94:
        raise ValueError('Keep the entire nineteen-runtime and ninety-four-role closure')
    return dict(complete=True,source_only=True,scientific_import_or_execution=False,
        local_numerical_fixtures_performed=False,whole_outputs=outputs,whole_source_roles=checked_roles)

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo',type=Path,required=True)
    p.add_argument('--outdir',type=Path,required=True)
    p.add_argument('--verify-existing',action='store_true')
    a=p.parse_args()
    result=run(a.repo,a.outdir,verify_existing=a.verify_existing)
    print(json.dumps(result,sort_keys=True))

if __name__=='__main__':
    main()
